values ('20260928T134240Z-8a7541', 'recipes', 2, $yl_fe3ecbb03b96$t!\r\nBake with the lid on: in Dutch oven for 20 minutes at 220°C.\r\nBake with the lid off: in Dutch oven for 15 minutes at 180°C.\r\nRest on the bench: for a minimum of 1 hour before slicing.", "protein": null, "category": "sourdough", "created_at": "2026-06-18T12:30:39.361085+00:00", "source_url": null, "updated_at": "2026-06-20T01:51:06.954687+00:00", "cook_time_min": 720, "substitutions": null}, {"slug": "spaghetti-bolognese", "tips": "Slow simmer option: really takes this to another level, if you have the time! Add 3/4 cup of water, cover with lid and simmer on very low for 2 - 2.5 hours, stirring every 30 minutes or so. Uncover, simmer 20 minutes to thicken sauce.", "title": "Spaghetti Bolognese", "method": "Sauté: Heat oil in a large pot or deep skillet over medium high heat. Add onion and garlic, cook for 3 minutes or until light golden and softened.\nCook beef: Turn heat up to high and add beef. Cook, breaking it up as your go, until browned.\nReduce wine: Add red wine. Bring to simmer and cook for 1 minute, scraping the bottom of the pot, until the alcohol smell is gone.\nSimmer: Add the remaining ingredients. Stir, bring to a simmer then turn down to medium so it bubbles gently. Cook for 20 - 30 minutes (no lid), adding water if the sauce gets too thick for your taste. Stir occasionally.\nTaste and add more salt it desired.", "protein": "beef, pork", "category": "main", "created_at": "2026-07-20T09:31:39.395123+00:00", "source_url": "https://www.recipetineats.com/spaghetti-bolognese/#recipe", "updated_at": "2026-07-20T09:31:39.395123+00:00", "cook_time_min": 30, "substitutions": "Red wine can be replaced with water or stock"}, {"slug": "toasted-granola", "tips": null, "title": "Toasted Granola", "method": "Toast the seeds and coconut chips in a dry frying pan set aside.\r\nMix together wet ingredients.\r\nAdd dry ingredients to the wet ingredients - should be clumpy if not, add more coconut oil.\r\nPut on a tray and bake for around 8 minutes , cool completely and the store in an airtight container.", "protein": "nuts_seeds", "category": "sweet_treat", "created_at": "2026-06-18T12:30:39.669181+00:00", "source_url": "https://www.melanieskitchen.co.nz/sarah-days-granola/", "updated_at": "2026-06-20T01:51:06.954687+00:00", "cook_time_min": 15, "substitutions": null}, {"slug": "vegemite-scroll", "tips": null, "title": "Vegemite Scroll", "method": "Mix: warm milk an discard together in bowl.\r\nMelt: butter (for the dough) in 15 second burst in microwave.\r\nAdd: egg and butter (for the dough) to the milk & discard.\r\nMix in: four, salt, baking powder and baking soda until shaggy dough forms. Cover and rest for 20-30mins.\r\nUncover: and knead for 5 minutes. Rest for another 30 minutes.\r\nPreheat oven: to 180°c.\r\nMelt: butter (for the dough) in 15 second burst in microwave, mix together with Vegemite.\r\nRoll out dough: into square.\r\nSpread: Vegemite mixture across dough & sprinkle the cheese evenly (save some for topping).\r\nCut up: dough into 12 strips (a pizza cutter is good for this) & roll each up.\r\nPlace on oven tray evenly: and sprinkle remaining cheese on top.\r\nBake: covered at 180°c for 10 mins.\r\nRemove lid and bake for a further 10 mins.", "protein": null, "category": "sourdough", "created_at": "2026-06-18T12:30:40.28402+00:00", "source_url": null, "updated_at": "2026-06-20T01:51:06.954687+00:00", "cook_time_min": 80, "substitutions": null}, {"slug": "vegetable-chilli", "tips": null, "title": "Vegetable Chilli", "method": "Sauté base vegetables: Heat olive oil in a frying pan over medium heat. Cook onion until softened, then add garlic, carrots, celery, and capsicum. Cook another 2-3 mins.\r\nAdd spices: Stir in cumin, paprika, coriander, oregano, chilli flakes, and tomato paste. Cook 1–2 min until fragrant.\r\nTransfer to slow cooker: Add sautéed mix plus tomatoes, beans, lentils, stock, soy sauce, sugar, and any optional ingredients.\r\nSlow cook: Cover and cook on low for 6–8 hours or high for 3–4 hours. Stir occasionally if possible.\r\nFinish & serve: Taste and adjust seasoning. Add water if needed. Serve with your other favourite Mexican ingredients (rice, salsa, avocado, lime, tortilla chips, tortillas).", "protein": "beans, lentils", "category": "slow_cooker", "created_at": "2026-06-18T12:30:39.913849+00:00", "source_url": null, "updated_at": "2026-06-20T01:51:06.954687+00:00", "cook_time_min": 480, "substitutions": null}, {"slug": "vietnamese-dressing-nuoc-cham", "tips": null, "title": "Vietnamese Dressing (Nuoc Cham)", "method": "Dissolve: sugar in lime juice, vinegar, and water.\r\nStir in: fish sauce, garlic, and chilli.\r\nTaste: and adjust — more sugar for sweetness, water to mellow.\r\nServe: with salads, grilled meats, or noodle bowls.", "protein": null, "category": "condiment", "created_at": "2026-06-18T12:30:40.558714+00:00", "source_url": "https://chat.openai.com/", "updated_at": "2026-06-20T01:51:06.954687+00:00", "cook_time_min": 5, "substitutions": null}, {"slug": "whiskey-sour", "tips": null, "title": "Whiskey Sour", "method": "Chill glass: you'll use to serve\r\nAdd: all ingredients to shaker with a handful of ice\r\nShake: thoroughly\r\nPour: into glass, keeping the ice in the shaker\r\nTop: with a dash of bitters", "protein": null, "category": "drink", "created_at": "2026-06-18T12:30:40.898585+00:00", "source_url": "https://www.instagram.com/__tablemanners__/", "updated_at": "2026-06-20T01:51:06.954687+00:00", "cook_time_min": 3, "substitutions": null}]$yl_fe3ecbb03b96$)
